// voxel builder
const boxGeo = new THREE.BoxGeometry(1,1,1);
const materials = {};
function mat(color){ if(!materials[color]) materials[color] = new THREE.MeshLambertMaterial({color}); return materials[color]; }
const groups = {};
function voxel(x,y,z,color,sx=1,sy=1,sz=1){
  const key = color+'|'+sx+','+sy+','+sz;
  if(!groups[key]) groups[key] = {mat:mat(color), list:[]};
  groups[key].list.push([x,y,z]);
}
function build(){
  for(const key in groups){
    const g = groups[key];
    const [sx,sy,sz] = key.split('|')[1].split(',').map(Number);
    const inst = new THREE.InstancedMesh(boxGeo, g.mat, g.list.length);
    const m = new THREE.Matrix4();
    g.list.forEach((p,i)=>{
      m.makeScale(sx,sy,sz);
      m.setPosition(p[0], p[1]+sy/2, p[2]);
      inst.setMatrixAt(i,m);
    });
    inst.castShadow = true; inst.receiveShadow = true;
    scene.add(inst);
  }
}

